"""Mirror of checker.py used only for generating (likely accepted) programs."""
import sys
sys.path.insert(0,'/app')
from language import kind, KINDS

INT=frozenset(['int']); TEXT=frozenset(['text']); BOOL=frozenset(['bool']); UNIT=frozenset(['unit'])

class Bad(Exception): pass

def is_fn(t): return isinstance(t,tuple)

def shape(t):
    return ('fn',shape(t[1])) if is_fn(t) else ('scalar',t)

def join(a,b):
    if is_fn(a) and is_fn(b):
        return ('fn',join(a[1],b[1]),frozenset(a[2])|frozenset(b[2]))
    if isinstance(a,frozenset) and isinstance(b,frozenset): return a|b
    raise Bad('join')

class Model:
    def __init__(self,env,facts,bounds,inputs):
        self.env=env; self.facts=facts; self.bounds=bounds; self.inputs=inputs
    def copy(self): return Model(dict(self.env),dict(self.facts),self.bounds,self.inputs)

def etype(e,m):
    op=e[0]
    if op=='lit': return frozenset([kind(e[1])]),frozenset()
    if op=='var':
        if e[1] not in m.env: raise Bad('var')
        return m.env[e[1]],frozenset()
    if op=='get':
        if e[1] not in m.facts: raise Bad('get')
        return m.facts[e[1]],frozenset()
    if op=='is':
        if e[1] not in m.facts: raise Bad('is')
        return BOOL,frozenset()
    if op=='not':
        t,w=etype(e[1],m)
        if t!=BOOL: raise Bad('not')
        return BOOL,w
    if op in ('add','lt'):
        ta,wa=etype(e[1],m); tb,wb=etype(e[2],m)
        if ta!=INT or tb!=INT: raise Bad(op)
        return (INT if op=='add' else BOOL),wa|wb
    if op=='cat':
        ta,wa=etype(e[1],m); tb,wb=etype(e[2],m)
        if ta!=TEXT or tb!=TEXT: raise Bad('cat')
        return TEXT,wa|wb
    if op=='fn':
        inner=m.copy(); inner.facts=dict(m.bounds)
        w=do_block(e[1],inner)
        t,more=etype(e[2],inner)
        return ('fn',t,frozenset(w|more)),frozenset()
    if op=='call':
        t,w=etype(e[1],m)
        if not is_fn(t): raise Bad('call')
        for n in t[2]: m.facts[n]=m.bounds[n]
        return t[1],w|frozenset(t[2])
    raise Bad('op '+str(op))

def do_block(body,m):
    if not isinstance(body,list) or len(body)>128: raise Bad('block')
    writes=frozenset()
    for s in body:
        op=s[0]
        if op in ('let','assign','set','eval'):
            e=s[1] if op=='eval' else s[2]
            t,w=etype(e,m); writes|=w
            if op=='let':
                if s[1] in m.env or s[1] in m.bounds: raise Bad('let name')
                m.env[s[1]]=t
            elif op=='assign':
                if s[1] not in m.env or s[1] in m.inputs: raise Bad('assign')
                if shape(t)!=shape(m.env[s[1]]): raise Bad('assign shape')
                m.env[s[1]]=t
            elif op=='set':
                if s[1] not in m.bounds or not isinstance(t,frozenset) or not t<=m.bounds[s[1]]: raise Bad('set')
                m.facts[s[1]]=t; writes|=frozenset([s[1]])
            continue
        t,w=etype(s[1],m); writes|=w
        if op=='if':
            if t!=BOOL: raise Bad('if cond')
            ea,eb=m.copy(),m.copy()
            g=s[1]
            if g[0]=='is':
                n,k=g[1:]
                if n not in m.facts: raise Bad('is guard')
                ea.facts[n]=m.facts[n]&frozenset([k])
                eb.facts[n]=m.facts[n]-frozenset([k])
            wa=do_block(s[2],ea) if all(ea.facts.values()) else frozenset()
            wb=do_block(s[3],eb) if all(eb.facts.values()) else frozenset()
            va=all(ea.facts.values()); vb=all(eb.facts.values())
            for n in list(m.env):
                if not vb: m.env[n]=ea.env[n]
                elif not va: m.env[n]=eb.env[n]
                else: m.env[n]=join(ea.env[n],eb.env[n])
            for n in list(m.facts):
                if not vb: m.facts[n]=ea.facts[n]
                elif not va: m.facts[n]=eb.facts[n]
                else: m.facts[n]=ea.facts[n]|eb.facts[n]
            writes|=wa|wb
        elif op=='repeat':
            if t!=INT: raise Bad('repeat count')
            for _ in range(64):
                before=(dict(m.env),dict(m.facts))
                nm=m.copy()
                writes|=do_block(s[2],nm)
                for n in list(m.env): m.env[n]=join(m.env[n],nm.env[n])
                for n in list(m.facts): m.facts[n]=m.facts[n]|nm.facts[n]
                if before==(dict(m.env),dict(m.facts)): break
            else: raise Bad('loop limit')
        else: raise Bad('stmt '+str(op))
    return writes
