import random,sys,json,copy
sys.path.insert(0,'/tmp/fz'); sys.path.insert(0,'/app')
from model import Model,etype,do_block,Bad,INT,TEXT,BOOL,UNIT,is_fn,shape,KINDS
from language import kind

LIT={'int':lambda r:r.randint(-2,2),'text':lambda r:r.choice(['a','bb','']),'bool':lambda r:r.choice([True,False]),'unit':lambda r:None}
def rand_lit(k,r): return LIT[k](r)

class Gen:
    def __init__(self,rng,cells,inputs,maxdepth=3):
        self.r=rng; self.cells=cells; self.inputs=inputs; self.maxdepth=maxdepth
        self.fresh=0

    def model0(self):
        env={n:frozenset([kind(v)]) for n,v in self.inputs.items()}
        facts={n:frozenset([kind(d['value'])]) for n,d in self.cells.items()}
        bounds={n:frozenset(d['types']) for n,d in self.cells.items()}
        return Model(env,facts,bounds,set(self.inputs))

    # ---- expression generation -------------------------------------------
    def fns_available(self,m,target):
        out=[]
        for n,t in m.env.items():
            if is_fn(t) and (target is None or t[1]==target): out.append(['var',n])
        return out

    def rand_expr(self,m,depth,target=None):
        """target: frozenset (exact static type wanted), 'fn' (function), or None."""
        r=self.r
        opts=[]
        if isinstance(target,frozenset):
            for k in target:
                opts.append((3,lambda k=k:['lit',rand_lit(k,r)]))
            for n,t in m.env.items():
                if isinstance(t,frozenset) and t==target: opts.append((3,lambda n=n:['var',n]))
            for c,t in m.facts.items():
                if t==target: opts.append((4,lambda c=c:['get',c]))
            if target==BOOL:
                for c in m.facts: opts.append((4,lambda c=c:['is',c,r.choice(list(KINDS))]))
                opts.append((3,lambda:['lt',self.rand_expr(m,depth+1,INT),self.rand_expr(m,depth+1,INT)]))
                opts.append((2,lambda:['not',self.rand_expr(m,depth+1,BOOL)]))
            if target==INT:
                opts.append((3,lambda:['add',self.rand_expr(m,depth+1,INT),self.rand_expr(m,depth+1,INT)]))
            if target==TEXT:
                opts.append((3,lambda:['cat',self.rand_expr(m,depth+1,TEXT),self.rand_expr(m,depth+1,TEXT)]))
            opts.extend((3,(lambda f=f:['call',f])) for f in self.fns_available(m,target))
        elif target=='fn':
            # build a function literal
            inner=m.copy(); inner.facts=dict(m.bounds)
            res=self.rand_expr(inner,depth+1,None)
            body=self.rand_block(inner,depth+1,r.randint(0,2))
            opts.append((3,lambda:['fn',body,res]))
            opts.extend((3,(lambda f=f:['call',f])) for f in self.fns_available(m,'fn'))
        else:
            # any type
            k=r.choice(['int','text','bool','unit'])
            opts.append((3,lambda k=k:['lit',rand_lit(k,r)]))
            for n in m.env: opts.append((3,lambda n=n:['var',n]))
            for c in m.facts: opts.append((4,lambda c=c:['get',c]))
            opts.append((2,lambda:self.rand_expr(m,depth+1,'fn')))
        if depth>=self.maxdepth:
            opts=[o for o in opts if o[1] is not None and o[1].__code__.co_argcount==0]
            # keep only leaf-ish options
            keep=[]
            for w,f in opts:
                try:
                    name=f.__code__
                except Exception: pass
                keep.append((w,f))
            opts=keep
        if not opts: return None
        tot=sum(w for w,_ in opts); x=r.random()*tot
        acc=0
        for w,f in opts:
            acc+=w
            if x<=acc:
                try: return f()
                except (TypeError,RecursionError,Bad): return None
        return None

    def rand_int(self,m,depth):
        e=self.rand_expr(m,depth,INT)
        return e if e is not None else ['lit',0]

    def rand_bool(self,m,depth):
        r=self.r
        if r.random()<0.5 and m.facts:
            return ['is',r.choice(list(m.facts)),r.choice(list(KINDS))]
        e=self.rand_expr(m,depth,BOOL)
        return e if e is not None else ['lit',True]

    # ---- statement generation -------------------------------------------
    def rand_block(self,m,depth,n):
        out=[]
        for _ in range(n):
            s=self.rand_stmt(m,depth)
            if s is not None: out.append(s)
        return out

    def rand_stmt(self,m,depth):
        r=self.r
        if depth>=self.maxdepth: return self.rand_simple(m,depth)
        x=r.random()
        if x<0.18:
            return ['if',self.rand_bool(m,depth),self.rand_block(m.copy(),depth+1,r.randint(0,2)),self.rand_block(m.copy(),depth+1,r.randint(0,2))]
        if x<0.32:
            return ['repeat',self.rand_int(m,depth),self.rand_block(m.copy(),depth+1,r.randint(1,2))]
        return self.rand_simple(m,depth)

    def rand_simple(self,m,depth):
        r=self.r
        x=r.random()
        if x<0.25:
            self.fresh+=1
            nm='v%d'%self.fresh
            tgt=r.choice([None,'fn',INT,TEXT,BOOL,UNIT])
            e=self.rand_expr(m,depth,tgt) if tgt is not None else self.rand_expr(m,depth,None)
            if e is None: e=['lit',rand_lit(r.choice(['int','text','bool','unit']),r)]
            return ['let',nm,e]
        if x<0.45 and m.env:
            cands=[n for n in m.env if n not in m.inputs]
            if not cands: return None
            n=r.choice(cands); t=m.env[n]
            if is_fn(t):
                e=self.rand_expr(m,depth,'fn')
            else:
                e=self.rand_expr(m,depth,t)
            if e is None: return None
            return ['assign',n,e]
        if x<0.75 and m.bounds:
            c=r.choice(list(m.bounds))
            b=m.bounds[c]
            k=r.choice(list(b))
            e=self.rand_expr(m,depth,frozenset([k]))
            if e is None: e=['lit',rand_lit(k,r)]
            return ['set',c,e]
        tgt=r.choice([None,'fn',INT,TEXT,BOOL,UNIT])
        e=self.rand_expr(m,depth,tgt) if tgt is not None else self.rand_expr(m,depth,None)
        if e is None: e=['lit',rand_lit(r.choice(['int','text','bool','unit']),r)]
        return ['eval',e]

def build_program(rng):
    cells={}
    ncell=rng.randint(1,2)
    for i in range(ncell):
        ks=rng.sample(['int','text','bool','unit'],rng.randint(1,3))
        name='c%d'%i
        cells[name]={'types':ks,'value':rand_lit(rng.choice(ks),rng)}
    inputs={}
    for i,n in enumerate(rng.sample(['i0','i1','i2'],rng.randint(0,2))):
        k=rng.choice(['int','text','bool','unit'])
        inputs[n]=rand_lit(k,rng)
    g=Gen(rng,cells,inputs,maxdepth=rng.randint(2,3))
    m=g.model0()
    body=[]
    for _ in range(rng.randint(4,10)):
        for _try in range(30):
            s=g.rand_stmt(m,0)
            if s is None: continue
            try:
                do_block([s],m.copy())
            except Exception: continue
            do_block([s],m)
            body.append(s)
            break
    return {'cells':cells,'inputs':inputs,'body':body}

if __name__=='__main__':
    import itertools
    from checker import check
    from interpreter import run
    rng=random.Random(int(sys.argv[1]) if len(sys.argv)>1 else 0)
    ok=0;acc=0;err=0
    for i in range(500):
        p=build_program(rng)
        try: check(p)
        except Exception as e: continue
        acc+=1
        try: res=run(p)
        except Exception as e: continue
        if res['status']=='type_error':
            err+=1
            print('FOUND',json.dumps(p))
            print(res['status'],res['steps'],res.get('message'))
            break
        else:
            ok+=1
    print('acc',acc,'normal',ok,'err',err)
