    def st(s):
        ids[id(s)]=len(ids)
        op=s[0]
        if op in ('let','assign','set'): ex(s[2])
        elif op=='eval': ex(s[1])
        elif op=='if':
            ex(s[1])
            for b in s[2]: st(b)
            for b in s[3]: st(b)
        elif op=='repeat':
            ex(s[1])
            for b in s[2]: st(b)
