LIT={'int':lambda r:r.randint(-2,2),'text':lambda r:r.choice(['a','bb','']),'bool':lambda r:r.choice([True,False]),'unit':lambda r:None}
def rl(k,r): return LIT[k](r)

class PG:
    def __init__(self,rng,cells,inputs,maxd=3):
        self.r=rng; self.cells=cells; self.inputs=inputs; self.maxd=maxd; self.fresh=0
    def m0(self):
        env={n:frozenset([kind(v)]) for n,v in self.inputs.items()}
        facts={n:frozenset([kind(d['value'])]) for n,d in self.cells.items()}
        bounds={n:frozenset(d['types']) for n,d in self.cells.items()}
        return Model(env,facts,bounds,set(self.inputs))
    def name(self):
        self.fresh+=1; return 'v%d'%self.fresh
    def ex(self,depth,hint=None):
        r=self.r
        if depth>=self.maxd:
            if hint in ('int','text','bool','unit'): return ['lit',rl(hint,r)]
            return ['lit',rl(r.choice(['int','text','bool','unit']),r)]
        x=r.random()
        if x<0.30:
            return ['lit',rl(hint if hint in ('int','text','bool','unit') else r.choice(['int','text','bool','unit']),r)]
        if x<0.45:
            ns=list(self.cells)+list(self.inputs)+[self.name() for _ in range(0)]
            pool=[n for n in list(self.cells)] 
            if r.random()<0.5 and pool: return ['get',r.choice(pool)]
            return ['var',r.choice(ns) if ns else self.name()]
        if x<0.55 and self.cells:
            return ['is',r.choice(list(self.cells)),r.choice(list(KINDS))]
        if x<0.62:
            return ['not',self.ex(depth+1,'bool')]
        if x<0.74:
            k='text' if hint=='text' else 'int'
            return [r.choice(['add','lt','cat']),self.ex(depth+1,k),self.ex(depth+1,k)]
        if x<0.85:
            return ['fn',self.blk(depth+1,r.randint(0,2)),self.ex(depth+1,hint)]
        return ['call',self.ex(depth+1,'fn')]
    def blk(self,depth,n):
        return [s for s in (self.stmt(depth) for _ in range(n)) if s is not None]
    def stmt(self,depth):
        r=self.r
        if depth<self.maxd-1:
            x=r.random()
            if x<0.18: return ['if',self.ex(depth+1,'bool'),self.blk(depth+1,r.randint(0,2)),self.blk(depth+1,r.randint(0,2))]
            if x<0.30: return ['repeat',self.ex(depth+1,'int'),self.blk(depth+1,r.randint(0,2))]
        x=r.random()
        if x<0.25: return ['let',self.name(),self.ex(depth+1,None)]
        if x<0.45: return ['assign','v%d'%r.randint(1,max(1,self.fresh)),self.ex(depth+1,None)]
        if x<0.70 and self.cells: return ['set',r.choice(list(self.cells)),self.ex(depth+1,None)]
        return ['eval',self.ex(depth+1,None)]

def build_perm(rng):
    cells={}
    for i in range(rng.randint(1,3)):
