        cells['c%d'%i]={'types':ks,'value':rl(rng.choice(ks),rng)}
    inputs={}
    for n in rng.sample(['i0','i1'],rng.randint(0,2)):
        inputs[n]=rl(rng.choice(['int','text','bool','unit']),rng)
    pg=PG(rng,cells,inputs,rng.randint(2,4))
    body=pg.blk(0,rng.randint(3,8))
    return {'cells':cells,'inputs':inputs,'body':body}

